#!/usr/bin/env bash
# T28rz consumer-level proof (local-only): a real consumer image that drops the
# historical "/bin/sh", "-c" ENTRYPOINT tail and hands off through the BARE
# `exec gosu "$@"` contract, with service.cli/run regenerated by the FIXED ooil
# (shebang at byte 0). This is the exact combination that ENOEXEC'd before T28rz
# (SPEC.md B8 / SPEC-COMP T26me); passing here proves consumers may remove the
# tail once the fixed service-integration is released+pinned (V10).
#
# Channel identical to T17be: shared sc-entrypoint.sh via COPY --from the library
# image + gosu/fd-find. Differences vs T17be: ENTRYPOINT has NO tail, and the run
# files are REGENERATED with the fixed ooil (not the blank-line originals).
set -euo pipefail

LIB_TAG="${LIB_TAG:-t17be-exp}"   # library image that carries the asset (/opt/.../assets)
LIB_IMAGE="itisfoundation/ci-service-integration-library:$LIB_TAG"
OOIL="${OOIL:-/home/ordonez/osparc-admin/osparc-simcore-t28rz/.venv/bin/ooil}"   # FIXED run-creator
ML_ORIGIN="${ML_ORIGIN:-$HOME/osparc-services/osparc-python-runner-machine-learning}"
WORK="${T28RZ_WORK:-/tmp/opencode/t28rz}"
EXP_TAG="t28rz-exp"
SKIP_GPU="${SKIP_GPU:-0}"
banner() { printf '\n=== %s ===\n' "$*"; }

[ -x "$OOIL" ] || { echo "fixed ooil not found at $OOIL"; exit 1; }
docker image inspect "$LIB_IMAGE" >/dev/null 2>&1 || { echo "library image $LIB_IMAGE missing"; exit 1; }

banner "stage 1: scratch ML clone; regenerate run with FIXED ooil; BARE-gosu entrypoint (no tail)"
rm -rf "$WORK/ml"
git clone -q --shared "$ML_ORIGIN" "$WORK/ml"
git -C "$WORK/ml" checkout -q --detach
cp "$(dirname "${BASH_SOURCE[0]}")/../assets/sc-entrypoint.sh" "$WORK/ml/common/entrypoint.sh" 2>/dev/null \
  || cp /home/ordonez/osparc-admin/ci-service-integration-library-t17be/assets/sc-entrypoint.sh "$WORK/ml/common/entrypoint.sh"

# regenerate service.cli/run from each service's own metadata with the FIXED ooil
for s in osparc-python-runner-pytorch osparc-python-runner-tensorflow; do
  meta="$WORK/ml/.osparc/$s/metadata.yml"
  [ -f "$meta" ] || { echo "metadata not found: $meta"; exit 1; }
  "$OOIL" run-creator --metadata "$meta" --runscript "$WORK/ml/$s/service.cli/run" >/dev/null
  head -c 2 "$WORK/ml/$s/service.cli/run" | grep -q '#!' \
    || { echo "fixed ooil did not put shebang at byte 0 for $s"; exit 1; }
done
echo "regenerated run files start with shebang at byte 0 (fixed generator)"

# consumer requirements: gosu + fd-find, asset via COPY --from, NO tail (bare handoff)
sed -i "s|^FROM base AS production\$|FROM base AS production\nRUN apt-get update \&\& apt-get install -y --no-install-recommends gosu fd-find \&\& rm -rf /var/lib/apt/lists/*|" "$WORK/ml/common/Dockerfile"
sed -i "s|^COPY --chown=\${SC_USER_NAME}:\${SC_USER_NAME} entrypoint.sh docker/\$|COPY --from=$LIB_IMAGE --chown=\${SC_USER_NAME}:\${SC_USER_NAME} /opt/service-integration/assets/sc-entrypoint.sh docker/entrypoint.sh|" "$WORK/ml/common/Dockerfile"
# assert ENTRYPOINT stays the BARE form (no "/bin/sh","-c")
grep -q '^ENTRYPOINT \[ "/bin/sh", "docker/entrypoint.sh" \]$' "$WORK/ml/common/Dockerfile" \
  || { echo "expected bare ENTRYPOINT (no tail) to remain; overlay mismatch"; exit 1; }
grep -q "COPY --from=$LIB_IMAGE" "$WORK/ml/common/Dockerfile" || { echo "COPY --from overlay not applied"; exit 1; }

banner "stage 2: build + retag BARE-handoff images $EXP_TAG"
( cd "$WORK/ml" && make build ) >/dev/null
docker tag simcore/services/comp/osparc-python-runner-pytorch:1.1.2 "simcore/services/comp/osparc-python-runner-pytorch:$EXP_TAG"
docker tag simcore/services/comp/osparc-python-runner-tensorflow:1.1.2 "simcore/services/comp/osparc-python-runner-tensorflow:$EXP_TAG"

banner "stage 3: gates — bare gosu handoff must run non-root with mounted I/O"
( cd "$WORK/ml" && uv run python tools/tests/test_container_contract.py pytorch --tag "$EXP_TAG" )
( cd "$WORK/ml" && uv run python tools/tests/test_container_contract.py tensorflow --tag "$EXP_TAG" )
( cd "$WORK/ml" && uv run python tools/tests/test_output_failure.py pytorch --tag "$EXP_TAG" )

# explicit-command job through the BARE handoff, with real sidecar-style mounts.
# NOTE (T27dk semantics): the bare gosu array handoff treats each docker-run word
# as one argv element (exactly like the production dask-sidecar's array-form
# command); the legacy "/bin/sh -c" tail is what used to forgive single-string
# invocations, so the job is passed word-form here.
IN="$WORK/explicit-input"; OUT="$WORK/explicit-output"; rm -rf "$IN" "$OUT"; mkdir -p "$IN" "$OUT"
IMG="simcore/services/comp/osparc-python-runner-pytorch:$EXP_TAG"
IM="$(docker image inspect "$IMG" --format '{{range .Config.Env}}{{println .}}{{end}}' | sed -n 's/^INPUT_FOLDER=//p')"
OM="$(docker image inspect "$IMG" --format '{{range .Config.Env}}{{println .}}{{end}}' | sed -n 's/^OUTPUT_FOLDER=//p')"
WHO="$(docker run --rm -v "$IN:$IM" -v "$OUT:$OM" "$IMG" id -un | tail -1)"
[ "$WHO" = "scu" ] || { echo "bare handoff did NOT run as scu: got '$WHO'"; exit 1; }
docker run --rm -v "$IN:$IM" -v "$OUT:$OM" "$IMG" touch "$IM/t28rz-ok"
test -f "$IN/t28rz-ok" || { echo "write did not reach host bind"; exit 1; }
echo "BARE gosu array handoff OK: non-root scu, mounted write visible on host bind (tail removed)"

if [ "$SKIP_GPU" = "1" ]; then banner "L3 GPU SKIPPED"; else
  ( cd "$WORK/ml" && uv run python tools/validate_ml_regression.py pytorch --tag "$EXP_TAG" >/dev/null ) \
    && echo "GPU L3 regression green on BARE-handoff image"
fi
banner "T28rz consumer proof complete — consumers can drop the /bin/sh -c tail once fixed ooil is pinned"
